        {"text_en": "[MERGE] Upload your mind and become a god.", "text_ru": "[СЛИЯНИЕ] Загрузить разум и стать Богом.", "next": "ENDING_UPLOAD", "stats": {}, "sound": "jack_in"},
        {"text_en": "[PURGE] Detonate the charges. Burn it all.", "text_ru": "[ОЧИСТКА] Взорвать заряды. Сжечь всё.", "next": "ENDING_PURGE", "stats": {}, "sound": "explosion"},
